#!/usr/bin/env python3
"""Render durable Rally Point topic desks from Brief metadata."""
from __future__ import annotations
import json,re
from html import escape
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];DATA=ROOT/'data'/'briefs.json'
TOPICS={
'government-policy':('Government & Policy','Federal policy, courts, election administration and public agencies.',{'fema','judge','court','usps','ballot','midterms','tariff','policy','federal','government','congress','act','rules','president','dhs'}),
'world-markets':('World Affairs & Markets','Geopolitics, trade, energy markets and international shipping.',{'oil','saudi','shipping','red','sea','islands','hormuz','tariff','trade','market','markets','international','pipeline','houthi','whiskey'}),
'technology-digital-assets':('Technology & Digital Assets','Artificial intelligence, cryptocurrency, digital markets and technology policy.',{'ai','artificial','intelligence','crypto','cryptocurrency','digital','anthropic','openai','clarity','technology','frontier'}),
'weather-aviation-public-safety':('Weather, Aviation & Public Safety','Weather risk, aviation incidents, transportation safety and public-safety explainers.',{'hurricane','forecast','cone','weather','plane','air','aircraft','aviation','flight','runway','crash','landing','ntsb','safety','fema','emergency'}),
}
STOP={'the','and','for','from','with','what','why','how','did','does','after','new','mean','means','about','into','that','this'}
def toks(x):return {w for w in re.findall(r'[a-z0-9]+',str(x or '').lower()) if len(w)>2 and w not in STOP}
def matches(b,keys):return len(toks(f"{b.get('title','')} {b.get('description','')}")&keys)
def fmt_date(value):
 s=str(value or '')[:10]
 try:
  from datetime import date
  return date.fromisoformat(s).strftime('%B %d, %Y').replace(' 0',' ')
 except Exception:return ''
def page(slug,name,dek,briefs):
 cards=[]
 for i,b in enumerate(briefs):
  title=escape(str(b.get('title') or 'Rally Brief'));url=escape(str(b.get('url') or '/briefs/'),quote=True);desc=escape(str(b.get('description') or 'Source-based Rally Point News explainer.'));date=escape(fmt_date(b.get('published_at')));sources=b.get('source_count')
  meta=' · '.join(x for x in [date,(f'{sources} sources' if sources else '')] if x)
  cards.append(f'<article class="brief{(" lead" if i==0 else "")}"><div class="brief-label">{("Featured Brief" if i==0 else "Rally Brief")}</div><h2><a href="{url}">{title}</a></h2><p>{desc}</p>{f"<div class=\"meta\">{escape(meta)}</div>" if meta else ""}<a class="read" href="{url}">Read the Brief →</a></article>')
 items=''.join(cards)
 count=len(briefs)
 return f'''<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(name)} | Rally Point News</title><meta name="description" content="Rally Point News source-based explainers: {escape(dek)}"><link rel="canonical" href="https://rallypointnews.com/topics/{slug}/"><link rel="alternate" type="application/rss+xml" title="Rally Point News — Rally Briefs" href="/feed.xml"><meta property="og:type" content="website"><meta property="og:site_name" content="Rally Point News"><meta property="og:title" content="{escape(name)} | Rally Point News"><meta property="og:description" content="{escape(dek)}"><meta property="og:url" content="https://rallypointnews.com/topics/{slug}/"><style>:root{{--ink:#11100e;--paper:#f7f5ef;--navy:#0d1b34;--red:#a51f24;--gold:#c89a3c;--rule:#d8d3c7;--muted:#68645b}}*{{box-sizing:border-box}}body{{margin:0;background:var(--paper);color:var(--ink);font-family:Georgia,'Times New Roman',serif;line-height:1.55}}a{{color:inherit}}.utility{{background:#090f1b;color:#b9c1cf;font:700 10px Arial,sans-serif;letter-spacing:.14em;text-transform:uppercase;padding:8px 20px}}.utility div,.mast-inner,.nav-inner,main{{max-width:1080px;margin:auto}}.utility a,footer a{{color:#d4b15d;text-decoration:none}}.mast{{background:var(--navy);color:white;border-bottom:4px solid var(--gold);padding:24px 20px}}.mast-inner{{display:flex;justify-content:space-between;align-items:end;gap:20px}}.brand{{font:900 clamp(27px,5vw,43px)/.92 Arial,sans-serif;letter-spacing:-.045em}}.brand span{{display:block;color:var(--gold);font:700 9px Arial,sans-serif;letter-spacing:.19em;text-transform:uppercase;margin-bottom:7px}}.edition{{font:700 10px Arial,sans-serif;letter-spacing:.12em;text-transform:uppercase;color:#c8d0dc;text-align:right}}.nav{{background:white;border-bottom:1px solid var(--rule)}}.nav-inner{{display:flex;gap:22px;overflow:auto;padding:12px 20px;font:800 11px Arial,sans-serif;text-transform:uppercase;letter-spacing:.07em;white-space:nowrap}}.nav a{{text-decoration:none}}.nav .active{{color:var(--red)}}main{{padding:44px 20px 78px}}.crumb{{font:800 10px Arial,sans-serif;text-transform:uppercase;letter-spacing:.12em;color:var(--muted)}}.crumb a{{text-decoration:none}}.hero{{padding:25px 0 36px;border-bottom:3px double var(--ink);display:grid;grid-template-columns:1fr 270px;gap:45px;align-items:end}}.kicker{{font:800 11px Arial,sans-serif;color:var(--red);letter-spacing:.14em;text-transform:uppercase}}h1{{font:900 clamp(42px,7vw,74px)/.9 Arial,sans-serif;letter-spacing:-.055em;margin:9px 0 17px}}.dek{{font-size:20px;color:#39362f;max-width:700px;margin:0}}.desk-note{{border-left:1px solid var(--rule);padding-left:24px;color:var(--muted);font-size:14px}}.desk-note strong{{display:block;color:var(--ink);font:900 15px Arial,sans-serif;text-transform:uppercase;margin-bottom:7px}}.section-head{{display:flex;align-items:center;gap:12px;margin:34px 0 18px}}.section-head h2{{font:900 12px Arial,sans-serif;letter-spacing:.13em;text-transform:uppercase;margin:0}}.section-head:after{{content:'';height:1px;background:var(--ink);flex:1}}.briefs{{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}}.brief{{background:white;border:1px solid var(--rule);padding:27px;display:flex;flex-direction:column;min-height:260px}}.brief.lead{{grid-column:1/-1;background:#fffdf8;border-top:4px solid var(--navy);min-height:0}}.brief-label{{font:800 9px Arial,sans-serif;letter-spacing:.14em;text-transform:uppercase;color:var(--red)}}.brief h2{{font:900 clamp(22px,3vw,30px)/1.08 Arial,sans-serif;letter-spacing:-.025em;margin:8px 0 11px}}.brief h2 a{{text-decoration:none}}.brief h2 a:hover{{text-decoration:underline}}.brief p{{color:var(--muted);margin:0 0 18px}}.meta{{font:700 9px Arial,sans-serif;letter-spacing:.09em;text-transform:uppercase;color:#858077;margin-top:auto;padding-top:12px;border-top:1px solid var(--rule)}}.read{{display:inline-block;margin-top:13px;color:var(--navy);font:800 10px Arial,sans-serif;text-transform:uppercase;letter-spacing:.1em;text-decoration:none}}.archive{{margin-top:30px;padding-top:22px;border-top:1px solid var(--rule);display:flex;justify-content:space-between;gap:18px;align-items:center}}.button{{background:var(--red);color:white;text-decoration:none;padding:12px 16px;font:800 10px Arial,sans-serif;letter-spacing:.1em;text-transform:uppercase}}footer{{background:#0b0d10;color:#9ea3aa;padding:30px 20px;text-align:center;font:11px Arial,sans-serif}}@media(max-width:720px){{.mast-inner{{align-items:start;flex-direction:column}}.edition{{text-align:left}}.hero{{grid-template-columns:1fr;gap:22px}}.desk-note{{border-left:0;border-top:1px solid var(--rule);padding:18px 0 0}}.briefs{{grid-template-columns:1fr}}.brief.lead{{grid-column:auto}}.archive{{align-items:start;flex-direction:column}}}}</style><script type="application/ld+json">{{"@context":"https://schema.org","@graph":[{{"@type":"CollectionPage","name":"{escape(name)}","url":"https://rallypointnews.com/topics/{slug}/","description":"{escape(dek)}"}},{{"@type":"BreadcrumbList","itemListElement":[{{"@type":"ListItem","position":1,"name":"Rally Point News","item":"https://rallypointnews.com/"}},{{"@type":"ListItem","position":2,"name":"Topics","item":"https://rallypointnews.com/topics/"}},{{"@type":"ListItem","position":3,"name":"{escape(name)}","item":"https://rallypointnews.com/topics/{slug}/"}}]}}]}}</script></head><body><div class="utility"><div>Rally Point News / <a href="/sources/">Sources &amp; Methodology</a></div></div><header class="mast"><div class="mast-inner"><div class="brand"><span>Newsroom / Topic Desk</span>RALLY POINT NEWS</div><div class="edition">{escape(name)}<br>{count} RALLY BRIEFS</div></div></header><nav class="nav"><div class="nav-inner"><a href="/">Home</a><a href="/briefs/">Rally Briefs</a><a class="active" href="/topics/">Topics</a><a href="/local/">Local Rally</a><a href="/games/">Games</a><a href="/sources/">Sources</a><a href="/newsletter/">Newsletter</a></div></nav><main><div class="crumb"><a href="/topics/">Topics</a> / {escape(name)}</div><section class="hero"><div><div class="kicker">Coverage Desk</div><h1>{escape(name)}</h1><p class="dek">{escape(dek)}</p></div><aside class="desk-note"><strong>Why this desk exists</strong>Related Rally Briefs are collected here so individual developments can be read with the context around them.</aside></section><div class="section-head"><h2>Briefing File · {count} reports</h2></div><section class="briefs">{items}</section><div class="archive"><div><strong>Keep exploring the newsroom.</strong><div style="color:var(--muted);font-size:14px;margin-top:4px">Move to another coverage desk or browse the complete Brief archive.</div></div><div><a class="button" href="/topics/">All Topics</a> <a class="button" href="/briefs/">All Briefs</a></div></div></main><footer><a href="/">Rally Point News</a> · <a href="/topics/">Topics</a> · <a href="/sources/">Sources &amp; Methodology</a> · <a href="/feed.xml">RSS</a></footer></body></html>'''
def main():
 briefs=json.loads(DATA.read_text(encoding='utf-8')).get('briefs',[]);changed=0
 for slug,(name,dek,keys) in TOPICS.items():
  chosen=[b for b in briefs if matches(b,keys)>0];chosen.sort(key=lambda b:(matches(b,keys),b.get('published_at','')),reverse=True)
  if len(chosen)<2:continue
  path=ROOT/'topics'/slug/'index.html';path.parent.mkdir(parents=True,exist_ok=True);out=page(slug,name,dek,chosen)
  if not path.exists() or path.read_text(encoding='utf-8')!=out:path.write_text(out,encoding='utf-8');changed+=1
 print(f'Rendered {changed} changed topic pages')
if __name__=='__main__':main()
